<?php
session_start();if(empty($_SESSION['user_id'])){header('Location:/pages/login.php');exit;}require_once __DIR__.'/../config/config.php';$userId=(int)$_SESSION['user_id'];
if(empty($_SESSION['notifications_csrf']))$_SESSION['notifications_csrf']=bin2hex(random_bytes(24));
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!hash_equals($_SESSION['notifications_csrf'],$_POST['csrf_token']??'')){http_response_code(403);exit('คำขอไม่ถูกต้อง');}
 if(isset($_POST['read_all'])){$pdo->prepare('UPDATE notifications SET is_read=1 WHERE user_id=? AND is_read=0')->execute([$userId]);header('Location:/pages/notifications.php?action=read_all');exit;}
 if(isset($_POST['delete_all'])){$pdo->prepare('DELETE FROM notifications WHERE user_id=?')->execute([$userId]);header('Location:/pages/notifications.php?action=deleted');exit;}
 if(isset($_POST['delete_one'])){$pdo->prepare('DELETE FROM notifications WHERE notification_id=? AND user_id=?')->execute([(int)($_POST['notification_id']??0),$userId]);header('Location:/pages/notifications.php?action=deleted_one');exit;}
}

function legacyAnnouncementUrl(PDO $pdo,array $notification):string{
 if(($notification['notification_type']??'')!=='system'||!str_starts_with((string)($notification['title']??''),'ประกาศใหม่จาก '))return '';
 $preview=preg_replace('/…$/u','',trim((string)($notification['message']??'')));
 if($preview==='')return '';
 foreach([['publisher_posts','publisher_id','publisher'],['shop_posts','shop_id','shop']] as [$table,$owner,$type]){try{$q=$pdo->prepare("SELECT $owner FROM $table WHERE content LIKE ? ORDER BY created_at DESC,post_id DESC LIMIT 1");$q->execute([$preview.'%']);$id=(int)$q->fetchColumn();if($id)return '/pages/partner_detail.php?type='.$type.'&id='.$id;}catch(Throwable $e){}}
 return '';
}
if(isset($_GET['read'])){$reviewNotice=$pdo->prepare("SELECT n.notification_id,n.related_review_id,r.user_id reviewer_id,r.book_id FROM notifications n LEFT JOIN book_reviews r ON r.review_id=n.related_review_id WHERE n.notification_id=? AND n.user_id=? AND n.notification_type='review'");$reviewNotice->execute([(int)$_GET['read'],$userId]);$reviewTarget=$reviewNotice->fetch(PDO::FETCH_ASSOC);if($reviewTarget){$pdo->prepare('UPDATE notifications SET is_read=1 WHERE notification_id=?')->execute([$reviewTarget['notification_id']]);if((int)$reviewTarget['reviewer_id']===$userId)header('Location:/pages/book_detail.php?id='.(int)$reviewTarget['book_id'].'#reviews');else header('Location:/pages/seller_review_management.php#review-'.(int)$reviewTarget['related_review_id']);exit;}}
if(isset($_GET['read'])){$id=(int)$_GET['read'];$stmt=$pdo->prepare('SELECT * FROM notifications WHERE notification_id=? AND user_id=?');$stmt->execute([$id,$userId]);$notification=$stmt->fetch(PDO::FETCH_ASSOC);if($notification){$pdo->prepare('UPDATE notifications SET is_read=1 WHERE notification_id=?')->execute([$id]);$targetUrl=(string)($notification['target_url']??'');if(str_starts_with($targetUrl,'/pages/')){header('Location:'.$targetUrl);exit;}$targetUrl=legacyAnnouncementUrl($pdo,$notification);if($targetUrl!==''){header('Location:'.$targetUrl);exit;}if($notification['notification_type']==='chat'){$conversation=(int)($notification['chat_conversation_id']??0);if(!$conversation){$latest=$pdo->prepare('SELECT conversation_id FROM chat_conversations WHERE customer_user_id=? ORDER BY last_message_at DESC,conversation_id DESC LIMIT 1');$latest->execute([$userId]);$conversation=(int)$latest->fetchColumn();}header('Location:/pages/chat.php'.($conversation?'?conversation='.$conversation:''));exit;}if($notification['notification_type']==='exchange'){header('Location:/pages/exchange_requests.php');exit;}if($notification['notification_type']==='follow'&&!empty($notification['related_user_id'])){header('Location:/pages/exchange_profile.php?user_id='.(int)$notification['related_user_id']);exit;}if(preg_match('/#(WN\d+)/',$notification['message'],$m)){if(in_array($_SESSION['role']??'',['publisher_admin','shop_admin'],true))header('Location:/pages/admin_orders.php?order='.urlencode($m[1]));else header('Location:/pages/order_receipt.php?number='.urlencode($m[1]));exit;}}header('Location:/pages/notifications.php');exit;}
$stmt=$pdo->prepare('SELECT *,UNIX_TIMESTAMP(created_at) AS created_ts FROM notifications WHERE user_id=? ORDER BY created_at DESC LIMIT 50');$stmt->execute([$userId]);$notifications=$stmt->fetchAll(PDO::FETCH_ASSOC);
$chatSenderStmt=$pdo->prepare("SELECT c.customer_user_id,c.seller_type,
    CASE WHEN c.customer_user_id=? THEN
        CASE WHEN c.seller_type='publisher' THEN CONCAT('สำนักพิมพ์ ',p.company_name) WHEN c.seller_type='shop' THEN CONCAT('ร้านหนังสือ ',s.shop_name) ELSE COALESCE(NULLIF(su.display_name,''),su.email) END
        ELSE COALESCE(NULLIF(cu.display_name,''),cu.email) END sender_name
    FROM chat_conversations c
    LEFT JOIN publishers p ON c.seller_type='publisher' AND p.publisher_id=c.seller_id
    LEFT JOIN shops s ON c.seller_type='shop' AND s.shop_id=c.seller_id
    LEFT JOIN users su ON c.seller_type='user' AND su.user_id=c.seller_id
    LEFT JOIN users cu ON cu.user_id=c.customer_user_id WHERE c.conversation_id=? LIMIT 1");
foreach($notifications as &$notice){if(($notice['notification_type']??'')==='chat'&&!empty($notice['chat_conversation_id'])){$chatSenderStmt->execute([$userId,(int)$notice['chat_conversation_id']]);$sender=$chatSenderStmt->fetchColumn();if($sender)$notice['title']='ข้อความใหม่จาก '.trim((string)$sender);}}unset($notice);
$unreadCount=count(array_filter($notifications,fn($notice)=>(int)$notice['is_read']===0));
function notificationTime(string $date):string{$seconds=max(0,time()-strtotime($date));if($seconds<60)return 'เมื่อสักครู่';if($seconds<3600)return floor($seconds/60).' นาทีที่แล้ว';if($seconds<86400)return floor($seconds/3600).' ชั่วโมงที่แล้ว';if($seconds<2592000)return floor($seconds/86400).' วันที่แล้ว';if($seconds<31536000)return floor($seconds/2592000).' เดือนที่แล้ว';return floor($seconds/31536000).' ปีที่แล้ว';}
$notificationTimeMap=[];foreach($notifications as $notice)$notificationTimeMap[(int)$notice['notification_id']]=(int)$notice['created_ts'];
?>
<script>window.wanawanNotificationTimes=<?=json_encode($notificationTimeMap)?>;</script>
<!DOCTYPE html><html lang="th"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>การแจ้งเตือน - วนวรรณ</title><link rel="stylesheet" href="../assets/css/styles.css?v=<?= filemtime(__DIR__.'/../assets/css/styles.css') ?>"><style>*{box-sizing:border-box}.wrap{max-width:1180px;margin:auto;padding:48px 40px 100px;min-height:620px}.notice-head{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-bottom:24px}.title{color:var(--secondary-color);font-size:36px;margin:0}.notice-actions{display:flex;gap:10px}.notice-actions form{margin:0}.manage-btn{min-width:125px;height:42px;border:1px solid #d3948b;border-radius:8px;background:#fff;color:#b66f68;font:inherit;font-weight:600;cursor:pointer}.manage-btn.primary{background:#d3948b;color:#fff}.manage-btn:disabled{opacity:.45;cursor:not-allowed}.notice{display:grid;grid-template-columns:48px 1fr auto;gap:18px;align-items:center;border:1px solid #ccd3c5;border-radius:13px;padding:17px 22px;margin-bottom:10px;background:#fff;color:inherit;text-decoration:none}.notice.unread{background:#fcfaf9}.icon{width:45px;height:45px;border-radius:50%;display:grid;place-items:center;background:#f3e3d8;color:var(--secondary-color);font-size:21px}.notice.order .icon{background:#e8eee5;color:#356a35}.notice h2{font-size:18px;margin:0 0 5px}.notice p{color:var(--text-muted);margin:0}.time{text-align:right;color:#7c8577;font-size:13px}.dot{display:inline-block;width:8px;height:8px;border-radius:50%;background:#3d7b37;margin-left:12px}.empty{text-align:center;color:var(--text-muted);padding:100px 20px}.success{padding:14px 18px;margin-bottom:20px;border-radius:10px;background:#e8f3e5;color:#356a35}.confirm-backdrop{position:fixed;inset:0;z-index:10000;display:grid;place-items:center;padding:20px;background:rgba(55,43,39,.42);backdrop-filter:blur(3px);opacity:0;visibility:hidden;transition:.2s}.confirm-backdrop.open{opacity:1;visibility:visible}.confirm-modal{width:min(460px,100%);padding:30px;border:1px solid #eadbd4;border-radius:20px;background:#fffaf7;box-shadow:0 22px 60px rgba(77,54,48,.22);transform:translateY(12px) scale(.98);transition:.2s}.confirm-backdrop.open .confirm-modal{transform:none}.confirm-icon{width:58px;height:58px;margin:0 auto 16px;border-radius:50%;display:grid;place-items:center;background:#f7dfe8;color:#b66f68;font-size:27px}.confirm-modal h2{margin:0;text-align:center;color:var(--secondary-color);font-size:24px}.confirm-modal p{margin:12px auto 24px;max-width:350px;text-align:center;color:var(--text-muted);line-height:1.7}.confirm-actions{display:grid;grid-template-columns:1fr 1fr;gap:12px}.confirm-btn{height:46px;border:1px solid #d3948b;border-radius:9px;font:inherit;font-weight:700;cursor:pointer}.confirm-cancel{background:#fff;color:#b66f68}.confirm-delete{background:#d3948b;color:#fff}.confirm-delete:hover{background:#c77f77}@media(max-width:700px){.notice-head{align-items:flex-start;flex-direction:column;gap:12px;margin-bottom:16px}.title{font-size:22px!important}.notice-actions{width:100%}.notice-actions form{flex:1}.manage-btn{width:100%;min-width:0;height:38px;font-size:13px}}
@media(max-width:600px){.wrap{padding:14px 12px 60px}.title{font-size:19px!important}.notice{grid-template-columns:38px 1fr;gap:12px;padding:13px 14px;border-radius:10px;margin-bottom:8px}.notice h2{font-size:14px;margin-bottom:3px}.notice p{font-size:12px;line-height:1.5}.icon{width:38px;height:38px;font-size:17px}.time{grid-column:2;text-align:left;font-size:11px}.dot{width:7px;height:7px;margin-left:8px}.manage-btn{height:36px;font-size:12px}.confirm-modal{padding:22px 16px}.confirm-modal h2{font-size:18px}.confirm-modal p{font-size:13px}.confirm-btn{height:42px;font-size:13px}.success{padding:10px 14px;font-size:13px;border-radius:8px}}</style></head><body><?php require __DIR__.'/../components/header.php';?><main class="wrap"><div class="notice-head"><h1 class="title">★ การแจ้งเตือน</h1><?php if($notifications):?><div class="notice-actions"><form method="post"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars($_SESSION['notifications_csrf'])?>"><button class="manage-btn primary" name="read_all" <?=$unreadCount?'':'disabled'?>>อ่านทั้งหมด</button></form><form method="post" id="deleteAllForm"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars($_SESSION['notifications_csrf'])?>"><input type="hidden" name="delete_all" value="1"><button class="manage-btn" type="button" id="openDeleteModal">ลบทั้งหมด</button></form></div><?php endif;?></div><?php if(($_GET['action']??'')==='read_all'):?><div class="success">ทำเครื่องหมายว่าอ่านการแจ้งเตือนทั้งหมดแล้ว</div><?php elseif(($_GET['action']??'')==='deleted'):?><div class="success">ลบการแจ้งเตือนทั้งหมดแล้ว</div><?php elseif(isset($_GET['submitted'])):?><div class="success">ส่งหลักฐานแล้ว คำสั่งซื้ออยู่ในสถานะ “รอตรวจสอบคำสั่งซื้อ”</div><?php endif;?><?php if(!$notifications):?><div class="empty">▧<p>ยังไม่มีการแจ้งเตือนในขณะนี้</p></div><?php else:foreach($notifications as $notice):?><a class="notice <?=htmlspecialchars($notice['notification_type'])?> <?=$notice['is_read']?'':'unread'?>" href="?read=<?=$notice['notification_id']?>"><span class="icon"><?=$notice['notification_type']==='order'?'▣':($notice['notification_type']==='exchange'?'↔':'☰')?></span><span><h2><?=htmlspecialchars($notice['title'])?></h2><p><?=htmlspecialchars($notice['message'])?></p></span><span class="time"><?=notificationTime($notice['created_at'])?><?=$notice['is_read']?'':'<i class="dot"></i>'?></span></a><?php endforeach;endif;?></main><?php if($notifications):?><div class="confirm-backdrop" id="deleteModal" role="dialog" aria-modal="true" aria-labelledby="deleteModalTitle"><div class="confirm-modal"><div class="confirm-icon"><svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="3 6 5 6 21 6"></polyline><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"></path><line x1="10" y1="11" x2="10" y2="17"></line><line x1="14" y1="11" x2="14" y2="17"></line></svg></div><h2 id="deleteModalTitle">ลบการแจ้งเตือนทั้งหมด?</h2><p>การแจ้งเตือนทั้งหมดของคุณจะถูกลบอย่างถาวร และไม่สามารถย้อนกลับได้</p><div class="confirm-actions"><button class="confirm-btn confirm-cancel" type="button" id="cancelDelete">ยกเลิก</button><button class="confirm-btn confirm-delete" type="button" id="confirmDelete">ลบทั้งหมด</button></div></div></div><?php endif;?><?php require __DIR__.'/../components/footer.php';?><?php if($notifications):?><script>(()=>{const modal=document.getElementById('deleteModal'),open=document.getElementById('openDeleteModal'),cancel=document.getElementById('cancelDelete'),confirmDelete=document.getElementById('confirmDelete'),form=document.getElementById('deleteAllForm');const show=()=>{modal.classList.add('open');document.body.style.overflow='hidden';cancel.focus()};const hide=()=>{modal.classList.remove('open');document.body.style.overflow='';open.focus()};open.addEventListener('click',show);cancel.addEventListener('click',hide);confirmDelete.addEventListener('click',()=>{confirmDelete.disabled=true;confirmDelete.textContent='กำลังลบ...';form.submit()});modal.addEventListener('click',e=>{if(e.target===modal)hide()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&modal.classList.contains('open'))hide()})})();</script><?php endif;?></body></html>
